package br.com.fintrack.service;
import br.com.fintrack.dto.TransacaoDTO; import br.com.fintrack.exception.SaldoInsuficienteException; import br.com.fintrack.model.TipoTransacao; import br.com.fintrack.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.time.LocalDate; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TransacaoServiceTest{
 @Mock TransacaoRepository transacoes; @Mock CategoriaRepository categorias; @Mock UsuarioRepository usuarios; @InjectMocks TransacaoService service;
 @Test void deveRecusarDespesaMaiorQueSaldo(){when(transacoes.sumValorByUsuarioIdAndTipo(1L,TipoTransacao.RECEITA)).thenReturn(new BigDecimal("1000.00"));when(transacoes.sumValorByUsuarioIdAndTipo(1L,TipoTransacao.DESPESA)).thenReturn(new BigDecimal("200.00"));TransacaoDTO dto=new TransacaoDTO(null,LocalDate.now(),"Compra",new BigDecimal("900.00"),TipoTransacao.DESPESA,"",false,2L,null);assertThrows(SaldoInsuficienteException.class,()->service.criar(1L,dto));verify(transacoes,never()).save(any());}
 @Test void deveCalcularSaldoDoPeriodo(){LocalDate i=LocalDate.of(2026,1,1),f=LocalDate.of(2026,12,31);when(transacoes.sumValorPeriodo(1L,TipoTransacao.RECEITA,i,f)).thenReturn(new BigDecimal("500.00"));when(transacoes.sumValorPeriodo(1L,TipoTransacao.DESPESA,i,f)).thenReturn(new BigDecimal("125.00"));assertEquals(new BigDecimal("375.00"),service.saldo(1L,i,f).saldo());}
}
